/* RASEEN — minimal frontend bootstrap (app.min.js)
 *
 * This file boots a tiny Telegram WebApp with ONLY the foundations:
 *   • Telegram WebApp init + initData passing
 *   • API client to the Cloudflare Worker (action-based POST /api)
 *   • Fetch user data (getState)
 *   • Home  (profile + balance)
 *   • Deposit (submit a TON tx hash for admin verification)
 *   • Withdraw (request a withdrawal to a TON address)
 *   • Referrals (invite link + active referrals list)
 *
 * Everything game-related (bikes, races, mining, tasks, missions,
 * upgrades, partner posts) has been deliberately removed. This is the
 * skeleton the rest of the project should be built on.
 */
(function () {
  // ── Config ────────────────────────────────────────────────────
  var API_URL  = "https://silent-block-bedf.ahmedrabieharoun.workers.dev/api";
  var BOT_USER = "YourBotUsername";                                // ← change this (no @)
  var TITLE    = "RASEEN";
  var VIEWPORT = "width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover";

  // ── Boot meta + head ──────────────────────────────────────────
  document.title = TITLE;
  var vp = document.querySelector('meta[name="viewport"]');
  if (!vp) { vp = document.createElement('meta'); vp.name = 'viewport'; document.head.appendChild(vp); }
  vp.setAttribute('content', VIEWPORT);

  // Inject Telegram WebApp SDK if missing
  if (!window.Telegram || !window.Telegram.WebApp) {
    var tgScript = document.createElement('script');
    tgScript.src = 'https://telegram.org/js/telegram-web-app.js';
    document.head.appendChild(tgScript);
  }

  // ── Styles ────────────────────────────────────────────────────
  var CSS = "" +
    "*{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent}" +
    ":root{--bg:#0a0f0a;--card:#101810;--border:rgba(255,255,255,.08);--text:#e8f5e9;--muted:rgba(232,245,233,.55);--accent:#7cb342;--accent2:#9ccc40;--red:#ef5350}" +
    "body{font-family:system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;background:var(--bg);color:var(--text);min-height:100vh;padding:0 0 76px;font-size:14px}" +
    ".topbar{display:flex;align-items:center;gap:10px;padding:12px 14px;background:var(--card);border-bottom:1px solid var(--border);position:sticky;top:0;z-index:5}" +
    ".av{width:36px;height:36px;border-radius:50%;background:#222;display:flex;align-items:center;justify-content:center;overflow:hidden;font-size:18px}" +
    ".av img{width:100%;height:100%;object-fit:cover}" +
    ".uname{font-weight:600;flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}" +
    ".bal{background:rgba(124,179,66,.12);border:1px solid rgba(124,179,66,.35);border-radius:18px;padding:6px 12px;font-weight:700;color:var(--accent)}" +
    ".sec{display:none;padding:14px}.sec.active{display:block}" +
    ".card{background:var(--card);border:1px solid var(--border);border-radius:14px;padding:14px;margin-bottom:12px}" +
    ".h{font-size:15px;font-weight:700;margin-bottom:10px;color:var(--accent)}" +
    ".row{display:flex;align-items:center;gap:10px;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--border)}.row:last-child{border-bottom:none}" +
    ".lbl{color:var(--muted);font-size:12px}.val{font-weight:600}" +
    "input,textarea{width:100%;background:#0a0f0a;border:1px solid var(--border);border-radius:10px;padding:10px 12px;color:var(--text);font-size:14px;font-family:inherit;margin-bottom:10px}" +
    "input:focus,textarea:focus{outline:none;border-color:var(--accent)}" +
    "button.btn{width:100%;background:linear-gradient(135deg,var(--accent),#4e7a20);border:none;border-radius:12px;padding:12px;color:#fff;font-weight:700;font-size:14px;cursor:pointer;font-family:inherit}" +
    "button.btn:disabled{opacity:.5;cursor:default}" +
    "button.btn.ghost{background:transparent;border:1px solid var(--border);color:var(--text)}" +
    ".nav{position:fixed;bottom:0;left:0;right:0;display:flex;background:var(--card);border-top:1px solid var(--border);z-index:10}" +
    ".nav-item{flex:1;padding:10px 4px;text-align:center;cursor:pointer;color:var(--muted);font-size:11px;font-weight:600}" +
    ".nav-item.active{color:var(--accent)}" +
    ".nav-ico{font-size:20px;margin-bottom:2px;display:block}" +
    ".msg{padding:10px 12px;border-radius:10px;margin-bottom:10px;font-size:13px;font-weight:600}" +
    ".msg.err{background:rgba(239,83,80,.15);border:1px solid rgba(239,83,80,.4);color:#ff8a86}" +
    ".msg.ok{background:rgba(124,179,66,.15);border:1px solid rgba(124,179,66,.4);color:var(--accent2)}" +
    ".ref-item{display:flex;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid var(--border)}.ref-item:last-child{border-bottom:none}" +
    ".ref-name{flex:1;font-weight:600;font-size:13px}.ref-meta{font-size:11px;color:var(--muted)}" +
    ".badge{padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700}" +
    ".badge.ok{background:rgba(124,179,66,.2);color:var(--accent2)}" +
    ".badge.pend{background:rgba(255,193,7,.18);color:#ffca28}" +
    ".loader{display:flex;align-items:center;justify-content:center;min-height:60vh;color:var(--muted)}" +
    ".hist-row{display:flex;justify-content:space-between;align-items:center;padding:8px 0;border-bottom:1px solid var(--border);font-size:12px}.hist-row:last-child{border-bottom:none}" +
    ".empty{text-align:center;color:var(--muted);padding:20px;font-size:13px}";

  var style = document.createElement('style');
  style.textContent = CSS;
  document.head.appendChild(style);

  // ── HTML shell ────────────────────────────────────────────────
  var HTML = "" +
    "<div id=\"app\">" +
    "  <div class=\"topbar\">" +
    "    <div class=\"av\" id=\"uAv\">👤</div>" +
    "    <div class=\"uname\" id=\"uName\">Player</div>" +
    "    <div class=\"bal\" id=\"uBal\">0 TON</div>" +
    "  </div>" +

    "  <div id=\"loader\" class=\"loader\">Loading…</div>" +

    "  <div class=\"sec\" id=\"secHome\">" +
    "    <div class=\"card\">" +
    "      <div class=\"h\">Account</div>" +
    "      <div class=\"row\"><span class=\"lbl\">Telegram ID</span><span class=\"val\" id=\"hmId\">—</span></div>" +
    "      <div class=\"row\"><span class=\"lbl\">Username</span><span class=\"val\" id=\"hmUser\">—</span></div>" +
    "      <div class=\"row\"><span class=\"lbl\">TON Balance</span><span class=\"val\" id=\"hmBal\">0</span></div>" +
    "      <div class=\"row\"><span class=\"lbl\">Total Referrals</span><span class=\"val\" id=\"hmRefs\">0</span></div>" +
    "    </div>" +
    "    <div class=\"card\">" +
    "      <div class=\"h\">Recent Balance Changes</div>" +
    "      <div id=\"hmLog\"><div class=\"empty\">No activity yet</div></div>" +
    "    </div>" +
    "  </div>" +

    "  <div class=\"sec\" id=\"secDeposit\">" +
    "    <div class=\"card\">" +
    "      <div class=\"h\">Deposit TON</div>" +
    "      <div class=\"row\"><span class=\"lbl\">Minimum</span><span class=\"val\" id=\"dpMin\">1 TON</span></div>" +
    "      <div class=\"row\"><span class=\"lbl\">Send to address</span><span class=\"val\" style=\"font-size:11px;word-break:break-all;text-align:right;max-width:60%\" id=\"dpAddr\">SET_DEPOSIT_ADDRESS</span></div>" +
    "      <p style=\"font-size:12px;color:var(--muted);margin:10px 0\">After sending TON from your wallet, paste the transaction hash and amount below. An admin will credit your balance shortly.</p>" +
    "      <input id=\"dpAmount\" type=\"number\" step=\"0.0001\" min=\"0\" placeholder=\"Amount in TON\">" +
    "      <input id=\"dpHash\" type=\"text\" placeholder=\"Transaction hash\">" +
    "      <div id=\"dpMsg\"></div>" +
    "      <button class=\"btn\" id=\"dpBtn\">Submit Deposit</button>" +
    "    </div>" +
    "    <div class=\"card\">" +
    "      <div class=\"h\">Recent Deposits</div>" +
    "      <div id=\"dpHist\"><div class=\"empty\">No deposits yet</div></div>" +
    "    </div>" +
    "  </div>" +

    "  <div class=\"sec\" id=\"secWithdraw\">" +
    "    <div class=\"card\">" +
    "      <div class=\"h\">Withdraw TON</div>" +
    "      <div class=\"row\"><span class=\"lbl\">Minimum</span><span class=\"val\" id=\"wdMin\">0.0001 TON</span></div>" +
    "      <div class=\"row\"><span class=\"lbl\">Fee</span><span class=\"val\" id=\"wdFee\">10%</span></div>" +
    "      <div class=\"row\"><span class=\"lbl\">Available</span><span class=\"val\" id=\"wdBal\">0 TON</span></div>" +
    "      <input id=\"wdAddr\" type=\"text\" placeholder=\"Your TON wallet address\">" +
    "      <input id=\"wdAmount\" type=\"number\" step=\"0.0001\" min=\"0\" placeholder=\"Amount in TON\">" +
    "      <div id=\"wdMsg\"></div>" +
    "      <button class=\"btn\" id=\"wdBtn\">Request Withdrawal</button>" +
    "    </div>" +
    "    <div class=\"card\">" +
    "      <div class=\"h\">Withdrawal History</div>" +
    "      <div id=\"wdHist\"><div class=\"empty\">No withdrawals yet</div></div>" +
    "    </div>" +
    "  </div>" +

    "  <div class=\"sec\" id=\"secRefs\">" +
    "    <div class=\"card\">" +
    "      <div class=\"h\">Invite Friends</div>" +
    "      <p style=\"font-size:12px;color:var(--muted);margin-bottom:10px\">Earn <b id=\"rfPct\">10%</b> commission on every deposit your referrals make.</p>" +
    "      <input id=\"rfLink\" type=\"text\" readonly>" +
    "      <button class=\"btn\" id=\"rfCopy\">Copy Invite Link</button>" +
    "      <button class=\"btn ghost\" id=\"rfShare\" style=\"margin-top:8px\">Share via Telegram</button>" +
    "    </div>" +
    "    <div class=\"card\">" +
    "      <div class=\"h\">Your Referrals (<span id=\"rfCount\">0</span>)</div>" +
    "      <div id=\"rfList\"><div class=\"empty\">No referrals yet</div></div>" +
    "    </div>" +
    "  </div>" +

    "  <div class=\"nav\">" +
    "    <div class=\"nav-item active\" data-sec=\"secHome\"><span class=\"nav-ico\">🏠</span>Home</div>" +
    "    <div class=\"nav-item\" data-sec=\"secDeposit\"><span class=\"nav-ico\">⬇️</span>Deposit</div>" +
    "    <div class=\"nav-item\" data-sec=\"secWithdraw\"><span class=\"nav-ico\">⬆️</span>Withdraw</div>" +
    "    <div class=\"nav-item\" data-sec=\"secRefs\"><span class=\"nav-ico\">👥</span>Friends</div>" +
    "  </div>" +
    "</div>";

  function boot() {
    document.body.innerHTML = HTML;
    bindNav();
    document.getElementById('dpBtn').onclick = submitDeposit;
    document.getElementById('wdBtn').onclick = submitWithdraw;
    document.getElementById('rfCopy').onclick = copyInviteLink;
    document.getElementById('rfShare').onclick = shareInviteLink;
    initTg();
  }

  // ── Telegram + State ──────────────────────────────────────────
  var state = { initData:'', user:null, data:null };

  function initTg() {
    var tries = 0;
    var iv = setInterval(function () {
      tries++;
      if (window.Telegram && window.Telegram.WebApp) {
        clearInterval(iv);
        try { window.Telegram.WebApp.ready(); window.Telegram.WebApp.expand(); } catch (_) {}
        state.initData = window.Telegram.WebApp.initData || '';
        loadState();
      } else if (tries > 40) {
        clearInterval(iv);
        // Allow running outside Telegram for local testing
        loadState();
      }
    }, 100);
  }

  // ── API client ────────────────────────────────────────────────
  function api(action, data) {
    return fetch(API_URL, {
      method : 'POST',
      headers: {
        'Content-Type' : 'application/json',
        'Authorization': 'Telegram ' + state.initData,
        'X-Action'     : action,
      },
      body: JSON.stringify({ action: action, data: data || {} }),
    }).then(function (r) { return r.json(); });
  }

  // ── Sections ──────────────────────────────────────────────────
  function bindNav() {
    var items = document.querySelectorAll('.nav-item');
    items.forEach(function (el) {
      el.onclick = function () {
        items.forEach(function (x) { x.classList.remove('active'); });
        el.classList.add('active');
        document.querySelectorAll('.sec').forEach(function (s) { s.classList.remove('active'); });
        document.getElementById(el.dataset.sec).classList.add('active');
      };
    });
  }

  // ── Render ────────────────────────────────────────────────────
  function loadState() {
    api('getState', { _initData: state.initData }).then(function (res) {
      var loader = document.getElementById('loader');
      if (!res || !res.success) {
        if (loader) loader.textContent = (res && res.error) || 'Failed to load.';
        return;
      }
      state.data = res.data;
      state.user = res.data.user;
      if (loader) loader.style.display = 'none';
      document.getElementById('secHome').classList.add('active');
      render();
    }).catch(function (e) {
      var loader = document.getElementById('loader');
      if (loader) loader.textContent = 'Network error: ' + e.message;
    });
  }

  function render() {
    var u   = state.user;
    var cfg = state.data.config || {};
    var refs = state.data.referrals || [];

    // Top bar
    document.getElementById('uName').textContent = (u.firstName || 'Player') + (u.lastName ? ' ' + u.lastName : '');
    document.getElementById('uBal').textContent  = fmt(u.tonBalance) + ' TON';
    var av = document.getElementById('uAv');
    if (u.photoUrl) av.innerHTML = '<img src="' + u.photoUrl + '" alt="">';

    // Home
    document.getElementById('hmId').textContent   = u.referralCode || '—';
    document.getElementById('hmUser').textContent = u.username ? '@' + u.username : '—';
    document.getElementById('hmBal').textContent  = fmt(u.tonBalance) + ' TON';
    document.getElementById('hmRefs').textContent = refs.length;
    renderLog(state.data.balanceLog || []);

    // Deposit
    document.getElementById('dpMin').textContent = (cfg.minDepositTon || 1) + ' TON';
    renderDepHist(state.data.depHistory || []);

    // Withdraw
    document.getElementById('wdMin').textContent = (cfg.minWithdrawTon || 0.0001) + ' TON';
    document.getElementById('wdFee').textContent = (cfg.withdrawFeePct  || 10) + '%';
    document.getElementById('wdBal').textContent = fmt(u.tonBalance) + ' TON';
    if (u.withdrawWallet) document.getElementById('wdAddr').value = u.withdrawWallet;
    renderWdHist(state.data.wdHistory || []);

    // Referrals
    document.getElementById('rfPct').textContent   = (cfg.refBonusPct || 10) + '%';
    document.getElementById('rfLink').value        = 'https://t.me/' + BOT_USER + '?start=' + u.referralCode;
    document.getElementById('rfCount').textContent = refs.length;
    renderRefs(refs);
  }

  function renderLog(log) {
    var el = document.getElementById('hmLog');
    if (!log.length) { el.innerHTML = '<div class="empty">No activity yet</div>'; return; }
    el.innerHTML = log.map(function (e) {
      var amt = (e.amount != null) ? (e.amount > 0 ? '+' : '') + fmt(e.amount) + ' TON' : '';
      return '<div class="hist-row"><span>' + e.type + '</span><span>' + amt + '</span></div>';
    }).join('');
  }

  function renderDepHist(list) {
    var el = document.getElementById('dpHist');
    if (!list.length) { el.innerHTML = '<div class="empty">No deposits yet</div>'; return; }
    el.innerHTML = list.map(function (d) {
      var badge = d.status === 'completed' ? '<span class="badge ok">Done</span>' : '<span class="badge pend">Pending</span>';
      return '<div class="hist-row"><span>' + fmt(d.amount) + ' TON</span>' + badge + '</div>';
    }).join('');
  }

  function renderWdHist(list) {
    var el = document.getElementById('wdHist');
    if (!list.length) { el.innerHTML = '<div class="empty">No withdrawals yet</div>'; return; }
    el.innerHTML = list.map(function (w) {
      var cls = w.status === 'approved' ? 'ok' : w.status === 'rejected' ? 'err' : 'pend';
      var label = w.status === 'approved' ? 'Approved' : w.status === 'rejected' ? 'Rejected' : 'Pending';
      return '<div class="hist-row"><span>' + fmt(w.amtRequested || w.amt) + ' TON</span><span class="badge ' + cls + '">' + label + '</span></div>';
    }).join('');
  }

  function renderRefs(refs) {
    var el = document.getElementById('rfList');
    if (!refs.length) { el.innerHTML = '<div class="empty">No referrals yet</div>'; return; }
    el.innerHTML = refs.map(function (r) {
      var avatar = r.photo ? '<img src="' + r.photo + '" alt="">' : '👤';
      var status = r.hasDeposited ? '<span class="badge ok">Active</span>' : '<span class="badge pend">New</span>';
      return '<div class="ref-item">' +
        '<div class="av">' + avatar + '</div>' +
        '<div style="flex:1;min-width:0">' +
          '<div class="ref-name">' + escapeHtml(r.name) + '</div>' +
          '<div class="ref-meta">Earned ' + fmt(r.earned) + ' TON • ' + (r.date || '') + '</div>' +
        '</div>' +
        status +
      '</div>';
    }).join('');
  }

  // ── Actions ───────────────────────────────────────────────────
  function submitDeposit() {
    var amount = parseFloat(document.getElementById('dpAmount').value);
    var hash   = document.getElementById('dpHash').value.trim();
    var msg    = document.getElementById('dpMsg');
    var btn    = document.getElementById('dpBtn');
    msg.innerHTML = '';

    if (!amount || amount <= 0)  return showMsg(msg, 'err', 'Enter a valid amount.');
    if (!hash || hash.length < 5) return showMsg(msg, 'err', 'Enter the transaction hash.');

    btn.disabled = true;
    api('deposit', { amount: amount, txHash: hash }).then(function (res) {
      btn.disabled = false;
      if (!res.success) return showMsg(msg, 'err', res.error || 'Failed.');
      showMsg(msg, 'ok', res.data.message || 'Deposit submitted.');
      document.getElementById('dpAmount').value = '';
      document.getElementById('dpHash').value   = '';
      loadState();
    }).catch(function (e) { btn.disabled = false; showMsg(msg, 'err', e.message); });
  }

  function submitWithdraw() {
    var addr   = document.getElementById('wdAddr').value.trim();
    var amount = parseFloat(document.getElementById('wdAmount').value);
    var msg    = document.getElementById('wdMsg');
    var btn    = document.getElementById('wdBtn');
    msg.innerHTML = '';

    if (!addr || addr.length < 10) return showMsg(msg, 'err', 'Enter a valid TON address.');
    if (!amount || amount <= 0)    return showMsg(msg, 'err', 'Enter a valid amount.');

    btn.disabled = true;
    api('withdraw', { address: addr, amount: amount }).then(function (res) {
      btn.disabled = false;
      if (!res.success) return showMsg(msg, 'err', res.error || 'Failed.');
      showMsg(msg, 'ok', 'Withdrawal request submitted. Net: ' + fmt(res.data.netAmt) + ' TON');
      document.getElementById('wdAmount').value = '';
      loadState();
    }).catch(function (e) { btn.disabled = false; showMsg(msg, 'err', e.message); });
  }

  function copyInviteLink() {
    var inp = document.getElementById('rfLink');
    inp.select(); inp.setSelectionRange(0, 99999);
    try { document.execCommand('copy'); alert('Invite link copied!'); }
    catch (_) { navigator.clipboard && navigator.clipboard.writeText(inp.value); }
  }

  function shareInviteLink() {
    var link = document.getElementById('rfLink').value;
    var text = 'Join me on ' + TITLE + ' and earn TON!';
    var url  = 'https://t.me/share/url?url=' + encodeURIComponent(link) + '&text=' + encodeURIComponent(text);
    if (window.Telegram && window.Telegram.WebApp && window.Telegram.WebApp.openTelegramLink) {
      window.Telegram.WebApp.openTelegramLink(url);
    } else {
      window.open(url, '_blank');
    }
  }

  // ── Utils ─────────────────────────────────────────────────────
  function fmt(n) {
    n = parseFloat(n) || 0;
    return n.toFixed(4).replace(/\.?0+$/, '') || '0';
  }
  function escapeHtml(s) {
    return String(s || '').replace(/[&<>"']/g, function (c) {
      return ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' })[c];
    });
  }
  function showMsg(el, cls, text) {
    el.innerHTML = '<div class="msg ' + cls + '">' + escapeHtml(text) + '</div>';
  }

  // ── Go ────────────────────────────────────────────────────────
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }
})();
